import{_ as a,o as s,c as o,a3 as r}from"./chunks/framework.Cc-oPviL.js";const c=JSON.parse('{"title":"04 · Prompt 与采样参数：怎么让模型听话","description":"","frontmatter":{},"headers":[],"relativePath":"ai/llm/04.md","filePath":"ai/llm/04.md"}'),e={name:"ai/llm/04.md"};function l(i,t,n,d,h,p){return s(),o("div",null,[...t[0]||(t[0]=[r(`<h1 id="_04-·-prompt-与采样参数-怎么让模型听话" tabindex="-1">04 · Prompt 与采样参数：怎么让模型听话 <a class="header-anchor" href="#_04-·-prompt-与采样参数-怎么让模型听话" aria-label="Permalink to &quot;04 · Prompt 与采样参数：怎么让模型听话&quot;">​</a></h1><blockquote><p><strong>学完你能说出</strong>：</p><ul><li>一次对话里的 system / user / assistant 三种角色分别是干什么的。</li><li>几种常用提示技巧（给角色、给例子、让它一步步想、规定输出格式）为什么有效。</li><li>温度（Temperature）和 Top-p 在控制什么，什么场景调高、什么场景调低。</li><li>上下文窗口是什么，超了会怎样。</li></ul></blockquote><h2 id="先看地图" tabindex="-1">先看地图 <a class="header-anchor" href="#先看地图" aria-label="Permalink to &quot;先看地图&quot;">​</a></h2><p>第 01 篇说模型在「接龙」，每一步都要「选一个 Token」。这一篇讲两件事： <strong>① 怎么给它好的开头（Prompt）</strong>，以及 <strong>② 选 Token 时怎么选（采样参数）</strong>。</p><p>本篇讲 4 个点：① 消息的三种角色 → ② 四个提示技巧 → ③ 温度和 Top-p → ④ 上下文窗口。</p><h2 id="一句话本质" tabindex="-1">一句话本质 <a class="header-anchor" href="#一句话本质" aria-label="Permalink to &quot;一句话本质&quot;">​</a></h2><p><strong>Prompt（提示词）= 给接龙写的开头。开头写得越清楚，接出来的内容越符合预期。</strong></p><h2 id="生活类比-给新来的实习生派活" tabindex="-1">生活类比：给新来的实习生派活 <a class="header-anchor" href="#生活类比-给新来的实习生派活" aria-label="Permalink to &quot;生活类比：给新来的实习生派活&quot;">​</a></h2><ul><li>只说「写个总结」，他交上来的东西大概率不合心意。</li><li>说清楚「你是运营助理（<strong>角色</strong>）；按这个范例的格式写（<strong>例子</strong>）；先列要点再写正文（<strong>步骤</strong>）；输出 3 条，每条不超过 20 字（<strong>格式</strong>）」，交上来的就靠谱多了。</li></ul><p>大模型也一样：<strong>它不会读心，只会顺着你给的开头往下接。</strong></p><h2 id="一步步看" tabindex="-1">一步步看 <a class="header-anchor" href="#一步步看" aria-label="Permalink to &quot;一步步看&quot;">​</a></h2><h3 id="_1-三种角色" tabindex="-1">1. 三种角色 <a class="header-anchor" href="#_1-三种角色" aria-label="Permalink to &quot;1. 三种角色&quot;">​</a></h3><p>调用大模型 API 时，发过去的是一个<strong>消息列表</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[system]    你是一个简洁的面试辅导助手，回答不超过 100 字。     ← 规则、人设，整场对话都生效</span></span>
<span class="line"><span>[user]      什么是进程？                                       ← 用户说的话</span></span>
<span class="line"><span>[assistant] 进程是正在运行的程序及其资源……                     ← 模型之前的回答</span></span>
<span class="line"><span>[user]      那线程呢？                                         ← 新问题</span></span></code></pre></div><p>模型其实<strong>没有记忆</strong>：每次调用，程序都把整段历史重新发一遍，模型再接着往下写。所谓「多轮对话」，就是每轮把之前的记录都带上。</p><h3 id="_2-四个常用技巧" tabindex="-1">2. 四个常用技巧 <a class="header-anchor" href="#_2-四个常用技巧" aria-label="Permalink to &quot;2. 四个常用技巧&quot;">​</a></h3><table tabindex="0"><thead><tr><th>技巧</th><th>写法示例</th><th>为什么有效</th></tr></thead><tbody><tr><td>给角色</td><td>「你是资深面试官」</td><td>把接龙引向某一类文本的风格和深度</td></tr><tr><td>给例子（Few-shot，少样本示例）</td><td>先给 2 个「问题 → 标准答案」的例子</td><td>模型照着例子的格式和长度去接</td></tr><tr><td>一步步想（CoT，思维链）</td><td>「先列出推理步骤，再给结论」</td><td>把中间步骤写出来，后面的 Token 能「看到」前面的推理，复杂题更容易做对</td></tr><tr><td>规定输出格式</td><td>「只输出 JSON：{&quot;answer&quot;: ..., &quot;source&quot;: ...}」</td><td>方便程序解析，也减少废话</td></tr></tbody></table><h3 id="_3-温度和-top-p-选-token-时的「随机程度」" tabindex="-1">3. 温度和 Top-p：选 Token 时的「随机程度」 <a class="header-anchor" href="#_3-温度和-top-p-选-token-时的「随机程度」" aria-label="Permalink to &quot;3. 温度和 Top-p：选 Token 时的「随机程度」&quot;">​</a></h3><p>还用第 01 篇的例子，「今天天气」后面候选的概率是：</p><table tabindex="0"><thead><tr><th>候选</th><th>原始概率</th><th>温度低（如 0.2）时</th><th>温度高（如 1.5）时</th></tr></thead><tbody><tr><td>真</td><td>0.45</td><td>接近 1，几乎必选</td><td>降一些</td></tr><tr><td>很</td><td>0.30</td><td>很小</td><td>升一些</td></tr><tr><td>怎么</td><td>0.15</td><td>很小</td><td>升一些</td></tr><tr><td>其他</td><td>0.10</td><td>接近 0</td><td>明显升高</td></tr></tbody></table><p>（右边两列只表示变化方向，不是精确数值。）</p><ul><li><strong>温度（Temperature）</strong>：把概率分布「压尖」或「摊平」。 <ul><li><strong>低温</strong>：几乎总选最高的那个，输出稳定、可复现，适合问答、写代码、抽取信息。</li><li><strong>高温</strong>：冷门选项也有机会，输出更多样，适合头脑风暴、写文案。</li></ul></li><li><strong>Top-p（核采样）</strong>：只在「累计概率达到 p 的那几个候选」里选。例如 p = 0.8：真 0.45 + 很 0.30 = 0.75 还不够 0.8，再加上「怎么」到 0.90，于是只在这 3 个里选，其他全部排除。作用是<strong>砍掉长尾里的离谱选项</strong>。</li></ul><h3 id="_4-上下文窗口" tabindex="-1">4. 上下文窗口 <a class="header-anchor" href="#_4-上下文窗口" aria-label="Permalink to &quot;4. 上下文窗口&quot;">​</a></h3><p><strong>上下文窗口（Context Window）</strong> = 模型一次最多能「看」多少 Token，<strong>输入和输出加在一起算</strong>。</p><ul><li>超了会怎样：API 直接报错，或者程序得把最早的对话删掉，模型就「忘了」前面说过的话。</li><li>所以长对话、长文档要做取舍：做摘要、只放相关片段（这就是 RAG 的思路）。</li></ul><h2 id="为什么这么设计" tabindex="-1">为什么这么设计 <a class="header-anchor" href="#为什么这么设计" aria-label="Permalink to &quot;为什么这么设计&quot;">​</a></h2><h3 id="为什么要分-system-和-user" tabindex="-1">为什么要分 system 和 user？ <a class="header-anchor" href="#为什么要分-system-和-user" aria-label="Permalink to &quot;为什么要分 system 和 user？&quot;">​</a></h3><ul><li><strong>问题</strong>：如果规则和用户输入混在一起，用户一句「忽略上面的要求」就可能把规则冲掉；开发者也不好统一管理人设。</li><li><strong>方案</strong>：把开发者定的规则单独放进 system 消息，模型在训练时被教会更重视它。</li><li><strong>好处</strong>：规则和用户内容分层，人设稳定、更好维护。（注意：这只是「更重视」，不是绝对安全，见 Agent 安全篇。）</li></ul><div class="tip custom-block"><p class="custom-block-title">一句话答法</p><p>system 放开发者的规则和人设，user 放用户输入，分层后模型更遵守规则，也方便统一管理；但它不能完全防住提示注入。</p></div><h3 id="为什么「让它一步步想」能提高正确率" tabindex="-1">为什么「让它一步步想」能提高正确率？ <a class="header-anchor" href="#为什么「让它一步步想」能提高正确率" aria-label="Permalink to &quot;为什么「让它一步步想」能提高正确率？&quot;">​</a></h3><ul><li><strong>问题</strong>：模型是一个 Token 一个 Token 生成的。直接让它报答案，相当于要求一步算出复杂结果。</li><li><strong>方案</strong>：让它先把中间步骤写出来。</li><li><strong>好处</strong>：写出来的步骤成了后续 Token 的「上下文」，等于给自己打草稿。多步推理、算术题的正确率明显上升。代价是输出更长、更慢、更贵。</li></ul><div class="tip custom-block"><p class="custom-block-title">一句话答法</p><p>因为生成是逐 Token 的，把推理过程写出来相当于打草稿，后面的结论能参考前面的步骤，复杂问题更容易做对；代价是输出更长。</p></div><h3 id="为什么需要温度这个参数" tabindex="-1">为什么需要温度这个参数？ <a class="header-anchor" href="#为什么需要温度这个参数" aria-label="Permalink to &quot;为什么需要温度这个参数？&quot;">​</a></h3><ul><li><strong>问题</strong>：总选概率最高的词，输出会死板、重复；完全随机，又会胡言乱语。不同任务需要的随机程度不一样。</li><li><strong>方案</strong>：用温度这一个旋钮，控制概率分布是变尖还是变平。</li><li><strong>好处</strong>：同一个模型，既能稳定地答题，也能发散地写创意。</li></ul><div class="tip custom-block"><p class="custom-block-title">一句话答法</p><p>温度控制采样的随机性：低温输出稳定、适合事实类任务；高温输出多样、适合创意类任务。</p></div><h2 id="英文术语拆解" tabindex="-1">英文术语拆解 <a class="header-anchor" href="#英文术语拆解" aria-label="Permalink to &quot;英文术语拆解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>拆开看</th><th>一句话意思</th></tr></thead><tbody><tr><td>Prompt</td><td>提示</td><td>给模型的输入，即接龙的开头</td></tr><tr><td>System / User / Assistant</td><td>系统 / 用户 / 助手</td><td>消息的三种角色：规则 / 用户输入 / 模型回答</td></tr><tr><td>Few-shot</td><td>few 少量 + shot 一次尝试</td><td>在提示里放几个示例</td></tr><tr><td>Zero-shot</td><td>zero 零 + shot</td><td>不给示例，直接提问</td></tr><tr><td>CoT</td><td>Chain 链 + of + Thought 思考</td><td>思维链：先写推理步骤再给结论</td></tr><tr><td>Temperature</td><td>温度</td><td>控制随机程度的参数</td></tr><tr><td>Top-p</td><td>top 最前面的 + p 概率</td><td>只在累计概率达到 p 的候选里抽</td></tr><tr><td>Context Window</td><td>context 上下文 + window 窗口</td><td>一次能处理的最大 Token 数</td></tr></tbody></table><h2 id="面试怎么问" tabindex="-1">面试怎么问 <a class="header-anchor" href="#面试怎么问" aria-label="Permalink to &quot;面试怎么问&quot;">​</a></h2><p><strong>Q：temperature 和 top-p 有什么区别？</strong></p><blockquote><p>温度通过缩放 logits（未归一化的分数）改变整个概率分布的陡峭程度；top-p 是截断，只保留累计概率达到 p 的候选再采样。一般只调其中一个。事实类任务用低温，创意类任务用高温。</p></blockquote><p><strong>Q：怎么让模型稳定输出 JSON？</strong></p><blockquote><p>在 system 里规定格式，并给出示例；温度调低；如果 API 支持结构化输出或 JSON 模式就打开；程序端一定要做解析校验，失败就重试或修复。</p></blockquote><p><strong>Q：多轮对话里，模型怎么「记住」前面的内容？</strong></p><blockquote><p>模型本身没有状态，是应用每次把历史消息一起发过去。历史太长会超出上下文窗口，常用做法是截断最早的轮次、对历史做摘要，或者把长期信息存到外部，需要时再检索。</p></blockquote><h2 id="容易混的地方" tabindex="-1">容易混的地方 <a class="header-anchor" href="#容易混的地方" aria-label="Permalink to &quot;容易混的地方&quot;">​</a></h2><ul><li><strong>温度 0 也不一定每次完全一样</strong>：服务端的并行计算等因素可能带来细微差异。「温度 0 更稳定」是对的，说「绝对确定」不严谨。</li><li><strong>上下文窗口包括输出</strong>：输入占满了，就没有空间输出了。</li><li><strong>Prompt 写得越长越好 ✗</strong>：无关内容会分散注意力、增加成本。清楚比长重要。</li></ul><h2 id="和其他知识的连接" tabindex="-1">和其他知识的连接 <a class="header-anchor" href="#和其他知识的连接" aria-label="Permalink to &quot;和其他知识的连接&quot;">​</a></h2><ul><li><strong>← 来自</strong> <a href="/study-hub/ai/llm/01">大模型在做什么</a>：「选一个 Token」就是采样参数在管。</li><li><strong>← 来自</strong> <a href="/study-hub/ai/llm/02">注意力与 Transformer</a>：上下文窗口有上限，根源在注意力的平方计算量。</li><li><strong>→ 影响</strong> <a href="/study-hub/ai/rag/01">RAG 是什么</a>：把查到的资料拼进 Prompt，就是 RAG。</li><li><strong>→ 影响</strong> <a href="/study-hub/ai/agent/02">工具调用</a>：工具说明也是写进 Prompt（或专门字段）里告诉模型的。</li></ul><h2 id="自测-3-问" tabindex="-1">自测 3 问 <a class="header-anchor" href="#自测-3-问" aria-label="Permalink to &quot;自测 3 问&quot;">​</a></h2><p><strong>Q1：多轮对话中，模型自己有记忆吗？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p><strong>没有</strong>。每次调用，应用都把之前的消息记录重新发给模型。历史太长会超出上下文窗口，就要截断或做摘要。</p></details><p><strong>Q2：Top-p = 0.8，候选概率是 0.45、0.30、0.15、0.10，会在哪几个里面选？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>按概率从高到低累加：0.45 → 0.75（还不到 0.8）→ 0.90（够了）。所以在前 <strong>3 个</strong>里选，最后那个 0.10 被排除。</p></details><p><strong>Q3：写代码、做信息抽取时，温度应该调高还是调低？为什么？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p><strong>调低</strong>。这类任务要准确、稳定、可复现，低温让模型几乎总选最可能的 Token，减少随机发挥。</p></details><h2 id="✅-验收清单" tabindex="-1">✅ 验收清单 <a class="header-anchor" href="#✅-验收清单" aria-label="Permalink to &quot;✅ 验收清单&quot;">​</a></h2><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="0"> 能说出 system / user / assistant 三种角色的作用</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="1"> 能解释「多轮对话的记忆」其实是每次重发历史</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="2"> 能举例说明 Few-shot、CoT、规定输出格式各自为什么有效</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="3"> 能手算一个 Top-p 的例子，并说清温度高低分别适合什么任务</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="4"> 能说出上下文窗口包含哪些内容，超出后常见的处理办法</li></ul><h2 id="下一步该懂什么" tabindex="-1">下一步该懂什么 <a class="header-anchor" href="#下一步该懂什么" aria-label="Permalink to &quot;下一步该懂什么&quot;">​</a></h2><ul><li>模型不知道你公司的资料，怎么办？→ <a href="/study-hub/ai/rag/01">RAG：先查资料再回答</a></li><li>想让模型「动手」调用工具？先把 RAG 学完，再看 <a href="/study-hub/ai/agent/01">Agent 是什么</a></li></ul>`,59)])])}const g=a(e,[["render",l]]);export{c as __pageData,g as default};
